using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ANM.TiposAnuncio;namespace GraphApi.Services.ANM.TiposAnuncio{    public class TiposAnuncioService : ITiposAnuncioService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposAnuncioService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposAnuncio>> GetTiposAnuncios(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM anm.TiposAnuncio (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposAnuncio>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposAnunciosDynamic(            int? tipoAnuncioID,            string? tipoAnuncio,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoAnuncioID, TipoAnuncio, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM anm.TiposAnuncio (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoAnuncioID.HasValue)            {                vSql.Append(" AND TipoAnuncioID = @TipoAnuncioID");                vParameters.Add("TipoAnuncioID",tipoAnuncioID);            }            if (!string.IsNullOrWhiteSpace(tipoAnuncio))            {                vSql.Append(" AND TipoAnuncio LIKE @TipoAnuncio");                vParameters.Add("TipoAnuncio",$"%{tipoAnuncio}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposAnuncio> CreateTiposAnuncio(clCreateTiposAnuncio objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO anm.TiposAnuncio                (TipoAnuncio, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoAnuncio, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoAnuncio,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoAnuncioID, TipoAnuncio, bEliminado                FROM anm.TiposAnuncio (NOLOCK)                WHERE TipoAnuncioID = @TipoAnuncioID;";            var vReadParams = new { TipoAnuncioID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposAnuncio>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposAnuncio con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposAnuncio?> UpdateTiposAnuncio(clUpdateTiposAnuncio objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoAnuncioID", objInput.TipoAnuncioID);            if (objInput.TipoAnuncio is not null)            {                vSets.Add("TipoAnuncio = @TipoAnuncio");                vParameters.Add("TipoAnuncio", objInput.TipoAnuncio);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE anm.TiposAnuncio                SET {vSetClause}                WHERE TipoAnuncioID = @TipoAnuncioID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoAnuncioID, TipoAnuncio, bEliminado                FROM anm.TiposAnuncio (NOLOCK)                WHERE TipoAnuncioID = @TipoAnuncioID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposAnuncio>(sSelect, new {  objInput.TipoAnuncioID });        }        public async Task<bool> DeleteTiposAnuncio(int nTiposAnuncioID)        {            const string sSql = @"                DELETE FROM anm.TiposAnuncio                WHERE TipoAnuncioID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposAnuncioID });            return vAffected > 0;        }    }}